import React, { useState, useEffect } from "react";
import { useHistory, useParams } from "react-router-dom";
import { getCar, updateCar } from "../../services/ApiCar"; // Hypothetical service function to fetch and update the car
import { toast } from "react-toastify";

export default function CardUpdateVoiture() {
  const { carId } = useParams();
  const history = useHistory();
  const [carDetails, setCarDetails] = useState({
    matricule: "",
    model: "",
    marque: "",
    TypeDeCarburant: "",
    Transmission: "",
    Categorie: "",
    NombreDeSiege: "",
    prix: "",
    prix_jour: "",
    couleur: "",
    disponible: true,
    voiture_image: null,
  });

  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    // Fetching the car data for the given carId
    const fetchCar = async () => {
      try {
        const data = await getCar(carId); // Hypothetical API call to fetch the car details
        setCarDetails(data);
      } catch (error) {
        console.error("Error fetching car details", error);
        toast.error("Erreur lors de la récupération des détails de la voiture");
      }
    };

    fetchCar();
  }, [carId]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setCarDetails({ ...carDetails, [name]: value });
    if (errors[name]) setErrors({ ...errors, [name]: "" });
  };

  const handleFileChange = (e) => {
    setCarDetails({ ...carDetails, voiture_image: e.target.files[0] });
    if (errors.voiture_image) setErrors({ ...errors, voiture_image: "" });
  };

  const validateForm = () => {
    const formErrors = {};
    const requiredFields = [
      "matricule",
      "model",
      "marque",
      "TypeDeCarburant",
      "prix",
      "prix_jour",
    ];

    requiredFields.forEach((field) => {
      if (!carDetails[field]) {
        formErrors[field] = `${field.charAt(0).toUpperCase() + field.slice(1)} est requis`;
      }
    });

    if (!carDetails.voiture_image) {
      formErrors.voiture_image = "Image requise";
    }

    setErrors(formErrors);
    return Object.keys(formErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!validateForm()) return;

    setIsSubmitting(true);

    const formData = new FormData();
    for (const key in carDetails) {
      if (carDetails[key] !== null && carDetails[key] !== undefined) {
        formData.append(key, carDetails[key]);
      }
    }

    try {
      await updateCar(carId, formData);
      toast.success("Voiture mise à jour avec succès !");
      history.push("/admin/Voiture");
    } catch (error) {
      console.error("Erreur lors de la mise à jour", error);
      toast.error(error.response?.data?.message || "Erreur lors de la mise à jour de la voiture");
    } finally {
      setIsSubmitting(false);
    }
  };

  const carburantOptions = ["Essence", "Diesel", "Hybride", "Électrique", "GPL", "Bioéthanol"];
  const transmissionOptions = ["Manuelle", "Automatique", "Semi-automatique"];
  const categorieOptions = ["Economique", "Compacte", "Berline", "SUV", "Monospace", "Sportive", "Luxe"];

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-blueGray-700 text-xl font-bold">Mettre à jour une voiture</h6>
          <button
            className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow hover:shadow-md"
            type="button"
            onClick={() => history.push("/admin/Voiture")}
          >
            Retour
          </button>
        </div>
      </div>

      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        <form onSubmit={handleSubmit}>
          <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">
            Informations véhicule
          </h6>

          <div className="flex flex-wrap">
            {/* Matricule */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Matricule*
                </label>
                <input
                  type="text"
                  name="matricule"
                  value={carDetails.matricule}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${
                    errors.matricule ? "border border-red-500" : ""
                  }`}
                  placeholder="AA-123-BB"
                />
                {errors.matricule && (
                  <p className="text-red-500 text-xs italic mt-1">{errors.matricule}</p>
                )}
              </div>
            </div>

            {/* Modèle */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Modèle*
                </label>
                <input
                  type="text"
                  name="model"
                  value={carDetails.model}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${
                    errors.model ? "border border-red-500" : ""
                  }`}
                  placeholder="Clio, 208, etc."
                />
                {errors.model && (
                  <p className="text-red-500 text-xs italic mt-1">{errors.model}</p>
                )}
              </div>
            </div>

            {/* Marque */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Marque*
                </label>
                <input
                  type="text"
                  name="marque"
                  value={carDetails.marque}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full ${
                    errors.marque ? "border border-red-500" : ""
                  }`}
                  placeholder="Renault, Peugeot, etc."
                />
                {errors.marque && (
                  <p className="text-red-500 text-xs italic mt-1">{errors.marque}</p>
                )}
              </div>
            </div>

            {/* Type de carburant */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Carburant*
                </label>
                <select
                  name="TypeDeCarburant"
                  value={carDetails.TypeDeCarburant}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full ${
                    errors.TypeDeCarburant ? "border border-red-500" : ""
                  }`}
                >
                  <option value="">Sélectionner</option>
                  {carburantOptions.map((option) => (
                    <option key={option} value={option}>
                      {option}
                    </option>
                  ))}
                </select>
                {errors.TypeDeCarburant && (
                  <p className="text-red-500 text-xs italic mt-1">{errors.TypeDeCarburant}</p>
                )}
              </div>
            </div>

            {/* Transmission */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Transmission
                </label>
                <select
                  name="Transmission"
                  value={carDetails.Transmission}
                  onChange={handleChange}
                  className="border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full"
                >
                  <option value="">Sélectionner</option>
                  {transmissionOptions.map((option) => (
                    <option key={option} value={option}>
                      {option}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {/* Catégorie */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Catégorie
                </label>
                <select
                  name="Categorie"
                  value={carDetails.Categorie}
                  onChange={handleChange}
                  className="border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full"
                >
                  <option value="">Sélectionner</option>
                  {categorieOptions.map((option) => (
                    <option key={option} value={option}>
                      {option}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {/* Nombre de sièges */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Nombre de sièges
                </label>
                <input
                  type="number"
                  name="NombreDeSiege"
                  value={carDetails.NombreDeSiege}
                  onChange={handleChange}
                  min="2"
                  max="9"
                  className="border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full"
                  placeholder="2-9"
                />
              </div>
            </div>
          </div>

          <hr className="mt-6 border-b-1 border-blueGray-300" />

          <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">
            Tarification
          </h6>

          <div className="flex flex-wrap">
            <div className="w-full lg:w-4/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Prix
                </label>
                <input
                  type="number"
                  name="prix"
                  value={carDetails.prix}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full ${
                    errors.prix ? "border border-red-500" : ""
                  }`}
                  placeholder="Prix d'achat"
                  min="0"
                  step="0.01"
                />
                {errors.prix && (
                  <p className="text-red-500 text-xs italic mt-1">{errors.prix}</p>
                )}
              </div>
            </div>

            <div className="w-full lg:w-4/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Prix-journalier
                </label>
                <input
                  type="number"
                  name="prix_jour"
                  value={carDetails.prix_jour}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full ${
                    errors.prix_jour ? "border border-red-500" : ""
                  }`}
                  placeholder="Prix location journalière"
                  min="0"
                  step="0.01"
                />
                {errors.prix_jour && (
                  <p className="text-red-500 text-xs italic mt-1">{errors.prix_jour}</p>
                )}
              </div>
            </div>

            <div className="w-full lg:w-4/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Couleur
                </label>
                <input
                  type="text"
                  name="couleur"
                  value={carDetails.couleur}
                  onChange={handleChange}
                  className="border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full"
                  placeholder="Couleur"
                />
              </div>
            </div>
          </div>

          {/* Image upload */}
          <div className="w-full px-4">
            <div className="relative w-full mb-3">
              <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                Image de la voiture*
              </label>
              <input
                type="file"
                name="voiture_image"
                onChange={handleFileChange}
                className="border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow w-full"
              />
              {errors.voiture_image && (
                <p className="text-red-500 text-xs italic mt-1">{errors.voiture_image}</p>
              )}
            </div>
          </div>

          <div className="text-center mt-6">
            <button
              type="submit"
              disabled={isSubmitting}
              className={`bg-lightBlue-500 text-white font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md focus:outline-none focus:ring-2 focus:ring-lightBlue-500 focus:ring-opacity-50 ${
                isSubmitting ? "opacity-50 cursor-not-allowed" : ""
              }`}
            >
              {isSubmitting ? "Mise à jour..." : "Mettre à jour"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
